mapper.sql:
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.DEL_YN = 'N'
  /* 스코프 필터: master/safe(companyWide=true)는 회사 전체, 그 외는 자기 사업장만 */

    AND A.SITE_CD = #{scopeSiteCd}



      AND A.STATUS_CD = #{statusCd}


      AND A.STATUS_CD IN ('COMPLETED', 'CANCELLED')



    AND A.SITE_CD = #{siteCd}


    AND A.MANAGER_USER_CD = #{managerUserCd}


    AND A.TITLE LIKE CONCAT('%', #{searchKeyword}, '%')

  /* 기간 필터: 종료일(ENDED_AT) 기준, 미종료(CANCELLED 등)는 등록일 보완.
     KST 벽시계 일자로 비교(파일 상단 시각 표시 규칙 — UTC 저장분의 00~09시 KST 하루 밀림 방지) */

    AND DATE(CONVERT_TZ(IFNULL(A.ENDED_AT, A.INSERT_DATE), @@SESSION.time_zone, '+09:00')) >= #{startDate}


    AND DATE(CONVERT_TZ(IFNULL(A.ENDED_AT, A.INSERT_DATE), @@SESSION.time_zone, '+09:00')) <= #{endDate}

mapper.select:
/* Tbm04Mapper.selectHistorySessionListCount */
SELECT COUNT(1)
FROM TB_TBM_SESSION A

/* Tbm04Mapper.selectHistoryStat */
/* 필터된 세션 집합(A)에 출결(AT)을 LEFT JOIN 하여 한 번에 집계. 출결 0건이면 모두 0. */
/* SUM은 행이 0건이면 NULL을 반환하므로 IFNULL로 0 보정(결과 record가 primitive int) */
SELECT
	COUNT(DISTINCT A.SESSION_CD)	AS sessionCount
	/* prafta-app-031: 참석=실입실(ENTRY_AT NOT NULL), 미이수=입실했으나 미완료(NULL or NOT_COMPLETED). 앱 정의와 통일. */
	, IFNULL(SUM(CASE WHEN AT.ENTRY_AT IS NOT NULL THEN 1 ELSE 0 END), 0)					AS attendanceCount
	, IFNULL(SUM(CASE WHEN AT.COMPLETION_STATUS_CD = 'COMPLETED' THEN 1 ELSE 0 END), 0)		AS completedCount
	, IFNULL(SUM(CASE WHEN AT.ENTRY_AT IS NOT NULL AND (AT.COMPLETION_STATUS_CD IS NULL OR AT.COMPLETION_STATUS_CD = 'NOT_COMPLETED') THEN 1 ELSE 0 END), 0)	AS notCompletedCount
FROM TB_TBM_SESSION A
	 /* PRAFTA-SUBCON-T5: JOIN 키에서 CMPNY_CD 제거(타사 참석자 포함). 세션 소유는 historyWhere 가 보장. */
	 LEFT OUTER JOIN TB_TBM_ATTENDANCE AT
	 	ON (
	 		A.SESSION_CD = AT.SESSION_CD
	 	AND AT.DEL_YN = 'N'
	 	)

/* Tbm04Mapper.selectSessionAttendances */ SELECT AT.ATTENDANCE_CD AS attendanceCd , AT.USER_TYPE_CD AS userTypeCd , TP.SYST_VAL_D_NM AS userTypeNm , AT.USER_CD AS userCd , CASE WHEN AT.USER_TYPE_CD = 'REGULAR' THEN RU.USER_NM ELSE DU.USER_NM END AS userNm , ND.NODE_NM AS deptNm , DU.MBL_NO_LAST4 AS mblNoLast4 , AT.ENTRY_TYPE_CD AS entryTypeCd , DATE_FORMAT(CONVERT_TZ(AT.ENTRY_AT, @@SESSION.time_zone, '+09:00'), '%Y-%m-%d %H:%i') AS entryAt , AT.EXIT_TYPE_CD AS exitTypeCd , DATE_FORMAT(CONVERT_TZ(AT.EXIT_AT, @@SESSION.time_zone, '+09:00'), '%Y-%m-%d %H:%i') AS exitAt , AT.EXIT_FORCED_REASON AS exitForcedReason , AT.ENTRY_SIGN_FILE_MGMT_CD AS entrySignFileMgmtCd , AT.EXIT_SIGN_FILE_MGMT_CD AS exitSignFileMgmtCd , AT.COMPLETION_STATUS_CD AS completionStatusCd , CS.SYST_VAL_D_NM AS completionStatusNm , AT.NOT_COMPLETED_REASON AS notCompletedReason , AT.STATUS_UPDATED_BY AS statusUpdatedBy , FNC_CMM_INFO_SRCH(AT.CMPNY_CD, 'USER_NM', AT.STATUS_UPDATED_BY, NULL) AS statusUpdatedByNm , DATE_FORMAT(CONVERT_TZ(AT.STATUS_UPDATED_AT, @@SESSION.time_zone, '+09:00'), '%Y-%m-%d %H:%i') AS statusUpdatedAt /* prafta-051-08: 앱 포그라운드 누적초(051-16 표시용, NULL=미수신/대리입실) */ , AT.APP_FOREGROUND_SEC AS appForegroundSec /* prafta-051-16: 입실 GPS 거리(m). 대리/검색입실은 NULL */ , AT.ENTRY_DISTANCE_M AS entryDistanceM /* 이상신호 요약(백엔드 집계) */ , ( SELECT COUNT(1) FROM TB_TBM_ATTENDANCE_EVENT EV WHERE EV.CMPNY_CD = AT.CMPNY_CD AND EV.ATTENDANCE_CD = AT.ATTENDANCE_CD AND EV.EVENT_TYPE_CD = 'BACKGROUND_OUT' ) AS backgroundCount , ( SELECT COUNT(1) FROM TB_TBM_ATTENDANCE_EVENT EV WHERE EV.CMPNY_CD = AT.CMPNY_CD AND EV.ATTENDANCE_CD = AT.ATTENDANCE_CD AND EV.EVENT_TYPE_CD = 'GPS_UPDATED' AND JSON_EXTRACT(EV.EVENT_DATA, '$.outOfRange') = TRUE ) AS gpsOutOfRangeCount , ( SELECT COUNT(1) FROM TB_TBM_ATTENDANCE_EVENT EV WHERE EV.CMPNY_CD = AT.CMPNY_CD AND EV.ATTENDANCE_CD = AT.ATTENDANCE_CD AND EV.EVENT_TYPE_CD = 'NETWORK_LOST' ) AS networkLostCount , ( SELECT COUNT(1) FROM TB_TBM_ATTENDANCE_EVENT EV WHERE EV.CMPNY_CD = AT.CMPNY_CD AND EV.ATTENDANCE_CD = AT.ATTENDANCE_CD ) AS eventCount /* PRAFTA-SUBCON-T5: 참석자 소속 회사코드(서비스가 1차 relabel 하여 응답에 담는다). */ , AT.CMPNY_CD AS cmpnyCd FROM TB_TBM_ATTENDANCE AT LEFT OUTER JOIN TB_USER RU ON ( AT.USER_TYPE_CD = 'REGULAR' AND AT.CMPNY_CD = RU.CMPNY_CD AND AT.USER_CD = RU.USER_CD ) LEFT OUTER JOIN TB_DAILY_USER DU ON ( AT.USER_TYPE_CD = 'DAILY' AND AT.CMPNY_CD = DU.CMPNY_CD AND AT.USER_CD = DU.USER_CD ) LEFT OUTER JOIN TB_SITE_NODE ND ON ( AT.USER_TYPE_CD = 'REGULAR' AND RU.CMPNY_CD = ND.CMPNY_CD AND RU.SITE_CD = ND.SITE_CD AND RU.NODE_CD = ND.NODE_CD ) LEFT OUTER JOIN ( SELECT D.SYST_VAL_D_CD, D.SYST_VAL_D_NM FROM TB_SYST_VAL_D D WHERE D.SYST_VAL_CD = 'SYS050' AND D.USE_YN = 'Y' ) TP ON ( AT.USER_TYPE_CD = TP.SYST_VAL_D_CD ) LEFT OUTER JOIN ( SELECT D.SYST_VAL_D_CD, D.SYST_VAL_D_NM FROM TB_SYST_VAL_D D WHERE D.SYST_VAL_CD = 'SYS053' AND D.USE_YN = 'Y' ) CS ON ( AT.COMPLETION_STATUS_CD = CS.SYST_VAL_D_CD )
WHERE AT.SESSION_CD = #{sessionCd} AND AT.DEL_YN = 'N'
AND AT.USER_TYPE_CD = #{userTypeCd}
AND AT.COMPLETION_STATUS_CD = #{completionStatusCd}
ORDER BY AT.ENTRY_AT IS NULL, AT.ENTRY_AT, AT.ATTENDANCE_CD

/* Tbm04Mapper.selectAttendanceEventCount */
SELECT COUNT(1)
FROM TB_TBM_ATTENDANCE_EVENT EV

WHERE EV.ATTENDANCE_CD = #{attendanceCd}
  AND EXISTS (
      SELECT 1
      FROM TB_TBM_ATTENDANCE AT
           INNER JOIN TB_TBM_SESSION S
              ON (
                  S.SESSION_CD = AT.SESSION_CD
              )
      WHERE AT.ATTENDANCE_CD = #{attendanceCd}
        AND EV.CMPNY_CD = AT.CMPNY_CD
        AND S.CMPNY_CD = #{gvCmpnyCd}
  )

/* Tbm04Mapper.countNodeAdminInSite */
SELECT COUNT(1)
FROM TB_SITE_NODE A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND (A.MAIN_ADMIN_CD = #{userCd} OR A.SUB_ADMIN_CD = #{userCd})

mapper.update:
/* Tbm04Mapper.updateCompletion */
UPDATE TB_TBM_ATTENDANCE
SET
	COMPLETION_STATUS_CD	= #{completionStatusCd}
	/* NOT_COMPLETED 시에만 사유 갱신. COMPLETED 복귀 시 기존 사유 보존(감사용). */
	, NOT_COMPLETED_REASON	= IFNULL(#{notCompletedReason}, NOT_COMPLETED_REASON)
	, STATUS_UPDATED_BY		= #{gvUserCd}
	, STATUS_UPDATED_AT		= NOW()
	, UPDATE_NO				= #{gvUserCd}
	, UPDATE_DATE			= NOW()

WHERE ATTENDANCE_CD = #{attendanceCd}
  AND DEL_YN = 'N'
  AND EXISTS (
      SELECT 1
      FROM TB_TBM_SESSION S
      WHERE S.SESSION_CD = TB_TBM_ATTENDANCE.SESSION_CD
        AND S.CMPNY_CD = #{gvCmpnyCd}
  )

mapper.select:
/* Tbm04Mapper.selectUserInfo */
SELECT DU.USER_CD AS userCd , 'DAILY' AS userTypeCd , DU.USER_NM AS userNm , DU.SITE_CD AS siteCd , ST.SITE_NM AS siteNm , NULL AS deptNm , DU.MBL_NO_LAST4 AS mblNoLast4 FROM TB_DAILY_USER DU LEFT OUTER JOIN TB_SITE ST ON ( DU.CMPNY_CD = ST.CMPNY_CD AND DU.SITE_CD = ST.SITE_CD ) WHERE DU.CMPNY_CD = #{gvCmpnyCd} AND DU.USER_CD = #{userCd}
SELECT RU.USER_CD AS userCd , 'REGULAR' AS userTypeCd , RU.USER_NM AS userNm , RU.SITE_CD AS siteCd , ST.SITE_NM AS siteNm , ND.NODE_NM AS deptNm , NULL AS mblNoLast4 FROM TB_USER RU LEFT OUTER JOIN TB_SITE ST ON ( RU.CMPNY_CD = ST.CMPNY_CD AND RU.SITE_CD = ST.SITE_CD ) LEFT OUTER JOIN TB_SITE_NODE ND ON ( RU.CMPNY_CD = ND.CMPNY_CD AND RU.SITE_CD = ND.SITE_CD AND RU.NODE_CD = ND.NODE_CD ) WHERE RU.CMPNY_CD = #{gvCmpnyCd} AND RU.USER_CD = #{userCd}

mapper.sql:
WHERE AT.CMPNY_CD = #{gvCmpnyCd}
  AND AT.USER_TYPE_CD = #{userTypeCd}
  AND AT.USER_CD = #{userCd}
  AND AT.DEL_YN = 'N'

    AND AT.COMPLETION_STATUS_CD = #{completionStatusCd}


    AND DATE(CONVERT_TZ(IFNULL(S.ENDED_AT, S.INSERT_DATE), @@SESSION.time_zone, '+09:00')) >= #{startDate}


    AND DATE(CONVERT_TZ(IFNULL(S.ENDED_AT, S.INSERT_DATE), @@SESSION.time_zone, '+09:00')) <= #{endDate}

mapper.select:
/* Tbm04Mapper.selectUserAttendanceCount */
SELECT COUNT(1)
FROM TB_TBM_ATTENDANCE AT
	 /* PRAFTA-SUBCON-T5: 세션 헤더 조인에서 CMPNY_CD 제거(타사 세션 이수 이력 포함). */
	 INNER JOIN TB_TBM_SESSION S
	 	ON (
	 		AT.SESSION_CD = S.SESSION_CD
	 	)

/* Tbm04Mapper.selectUserAttendanceSummary */
/* SUM은 행이 0건이면 NULL을 반환하므로 IFNULL로 0 보정(결과 record가 primitive int) */
SELECT
	COUNT(1)	AS totalCount
	, IFNULL(SUM(CASE WHEN AT.COMPLETION_STATUS_CD = 'COMPLETED' THEN 1 ELSE 0 END), 0)		AS completedCount
	, IFNULL(SUM(CASE WHEN AT.COMPLETION_STATUS_CD = 'NOT_COMPLETED' THEN 1 ELSE 0 END), 0)	AS notCompletedCount
	/* 평균 참여시간(분): 입실~종료가 모두 있는 출결 기준. 없으면 NULL */
	, ROUND(AVG(
		CASE
			WHEN AT.ENTRY_AT IS NOT NULL AND AT.EXIT_AT IS NOT NULL
				THEN TIMESTAMPDIFF(MINUTE, AT.ENTRY_AT, AT.EXIT_AT)
			ELSE NULL
		END
	  ))	AS avgDurationMin
FROM TB_TBM_ATTENDANCE AT
	 /* PRAFTA-SUBCON-T5: 세션 헤더 조인에서 CMPNY_CD 제거(타사 세션 이수 이력 포함). */
	 INNER JOIN TB_TBM_SESSION S
	 	ON (
	 		AT.SESSION_CD = S.SESSION_CD
	 	)

/* Tbm04Mapper.selectEvidenceOwnSessions */ SELECT A.SESSION_CD AS sessionCd , ST.SITE_NM AS siteNm , NULL AS hostCmpnyNm , A.TITLE AS title , FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'USER_NM', A.MANAGER_USER_CD, NULL) AS managerUserNm , DATE_FORMAT(CONVERT_TZ(A.STARTED_AT, @@SESSION.time_zone, '+09:00'), '%Y-%m-%d %H:%i') AS startedAt , DATE_FORMAT(CONVERT_TZ(A.ENDED_AT, @@SESSION.time_zone, '+09:00'), '%Y-%m-%d %H:%i') AS endedAt , IFNULL(A.EDU_MINUTES, 0) AS eduMinutes , ( SELECT COUNT(1) FROM TB_TBM_SESSION_RISK R WHERE R.CMPNY_CD = A.CMPNY_CD AND R.SESSION_CD = A.SESSION_CD ) AS riskCount , ( SELECT COUNT(1) FROM TB_TBM_ATTENDANCE AT /* PRAFTA-SUBCON-T5: 참석자 회사 조건 없음(타사 참석자 포함) - 세션 소유는 바깥 WHERE 가 보장. */ WHERE AT.SESSION_CD = A.SESSION_CD AND AT.DEL_YN = 'N' AND AT.ENTRY_AT IS NOT NULL ) AS attendanceCount , ( SELECT COUNT(1) FROM TB_TBM_ATTENDANCE AT WHERE AT.SESSION_CD = A.SESSION_CD AND AT.DEL_YN = 'N' AND AT.COMPLETION_STATUS_CD = 'COMPLETED' ) AS completedCount , 'N' AS sharedYn FROM TB_TBM_SESSION A LEFT OUTER JOIN TB_SITE ST ON ( A.CMPNY_CD = ST.CMPNY_CD AND A.SITE_CD = ST.SITE_CD ) WHERE A.CMPNY_CD = #{gvCmpnyCd} AND A.DEL_YN = 'N' AND A.STATUS_CD = 'COMPLETED' AND DATE(CONVERT_TZ(A.ENDED_AT, @@SESSION.time_zone, '+09:00')) >= #{fromDate} AND DATE(CONVERT_TZ(A.ENDED_AT, @@SESSION.time_zone, '+09:00')) <= #{toDate}
AND A.SITE_CD = #{scopeSiteCd}
AND A.SITE_CD = #{siteCd}
ORDER BY A.ENDED_AT LIMIT 1000

/* Tbm04Mapper.selectEvidenceWorkerSummary */ SELECT * FROM ( SELECT 'REGULAR' AS userTypeCd , U.USER_CD AS userCd , U.USER_NM AS userNm , IFNULL(AG.CNT, 0) AS tbmCount , IFNULL(AG.MINS, 0) AS tbmMinutes FROM TB_USER U LEFT OUTER JOIN ( SELECT AT.USER_TYPE_CD, AT.USER_CD, COUNT(1) AS CNT, SUM(IFNULL(S.EDU_MINUTES, 0)) AS MINS FROM TB_TBM_ATTENDANCE AT INNER JOIN TB_TBM_SESSION S ON ( AT.SESSION_CD = S.SESSION_CD ) WHERE AT.CMPNY_CD = #{gvCmpnyCd} AND AT.DEL_YN = 'N' AND AT.COMPLETION_STATUS_CD = 'COMPLETED' AND S.DEL_YN = 'N' AND S.STATUS_CD = 'COMPLETED' AND DATE(CONVERT_TZ(S.ENDED_AT, @@SESSION.time_zone, '+09:00')) >= #{fromDate} AND DATE(CONVERT_TZ(S.ENDED_AT, @@SESSION.time_zone, '+09:00')) <= #{toDate} GROUP BY AT.USER_TYPE_CD, AT.USER_CD ) AG ON ( AG.USER_TYPE_CD = 'REGULAR' AND AG.USER_CD = U.USER_CD ) WHERE U.CMPNY_CD = #{gvCmpnyCd} AND U.USE_YN = 'Y' AND (U.EMPLOYMENT_TYPE IS NULL OR U.EMPLOYMENT_TYPE <> 'DAILY')
AND U.SITE_CD = #{scopeSiteCd}
AND U.SITE_CD = #{siteCd}
UNION ALL
SELECT 'DAILY' AS userTypeCd , D.USER_CD AS userCd , D.USER_NM AS userNm , AG2.CNT AS tbmCount , AG2.MINS AS tbmMinutes FROM ( SELECT AT.USER_CD, COUNT(1) AS CNT, SUM(IFNULL(S.EDU_MINUTES, 0)) AS MINS FROM TB_TBM_ATTENDANCE AT INNER JOIN TB_TBM_SESSION S ON ( AT.SESSION_CD = S.SESSION_CD ) WHERE AT.CMPNY_CD = #{gvCmpnyCd} AND AT.DEL_YN = 'N' AND AT.USER_TYPE_CD = 'DAILY' AND AT.COMPLETION_STATUS_CD = 'COMPLETED' AND S.DEL_YN = 'N' AND S.STATUS_CD = 'COMPLETED' AND DATE(CONVERT_TZ(S.ENDED_AT, @@SESSION.time_zone, '+09:00')) >= #{fromDate} AND DATE(CONVERT_TZ(S.ENDED_AT, @@SESSION.time_zone, '+09:00')) <= #{toDate} GROUP BY AT.USER_CD ) AG2 INNER JOIN TB_DAILY_USER D ON ( D.CMPNY_CD = #{gvCmpnyCd} AND D.USER_CD = AG2.USER_CD )
AND D.SITE_CD = #{scopeSiteCd}
AND D.SITE_CD = #{siteCd}
) W ORDER BY W.userTypeCd, W.userNm LIMIT 3000

/* Tbm04Mapper.selectEvidenceSessionDetails */ SELECT S.SESSION_CD AS sessionCd , S.TITLE AS title , ST.SITE_NM AS siteNm , CASE WHEN S.CMPNY_CD = #{gvCmpnyCd} THEN NULL ELSE HC.CMPNY_NM END AS hostCmpnyNm , DATE_FORMAT(CONVERT_TZ(S.STARTED_AT, @@SESSION.time_zone, '+09:00'), '%Y-%m-%d %H:%i') AS startedAt , DATE_FORMAT(CONVERT_TZ(S.ENDED_AT, @@SESSION.time_zone, '+09:00'), '%Y-%m-%d %H:%i') AS endedAt , IFNULL(S.EDU_MINUTES, 0) AS eduMinutes , FNC_CMM_INFO_SRCH(S.CMPNY_CD, 'USER_NM', S.MANAGER_USER_CD, NULL) AS managerUserNm , S.GPS_VERIFY_TYPE_CD AS gpsVerifyTypeCd , S.GPS_VERIFY_RADIUS_M AS gpsVerifyRadiusM , S.CONTENT_BODY AS contentBody , CASE WHEN S.CMPNY_CD = #{gvCmpnyCd} THEN 'Y' ELSE 'N' END AS ownerYn FROM TB_TBM_SESSION S LEFT OUTER JOIN TB_SITE ST ON ( S.CMPNY_CD = ST.CMPNY_CD AND S.SITE_CD = ST.SITE_CD ) LEFT OUTER JOIN TB_CMPNY HC ON ( HC.CMPNY_CD = S.CMPNY_CD ) WHERE S.SESSION_CD IN #{cd} AND S.DEL_YN = 'N' AND ( ( S.CMPNY_CD = #{gvCmpnyCd}
AND S.SITE_CD = #{scopeSiteCd}
) OR EXISTS ( SELECT 1 FROM TB_TBM_ATTENDANCE AT WHERE AT.SESSION_CD = S.SESSION_CD AND AT.CMPNY_CD = #{gvCmpnyCd} AND AT.DEL_YN = 'N' AND AT.ENTRY_AT IS NOT NULL ) ) ORDER BY S.ENDED_AT

/* Tbm04Mapper.selectCmpnyNm */
SELECT C.CMPNY_NM
FROM TB_CMPNY C
WHERE C.CMPNY_CD = #{cmpnyCd}
LIMIT 1
